CREATE TABLE tenant (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL);
CREATE TABLE app_user (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES tenant(id), username VARCHAR(50) NOT NULL, password_hash VARCHAR(100) NOT NULL, display_name VARCHAR(80) NOT NULL, role VARCHAR(20) NOT NULL, UNIQUE(tenant_id,username));
CREATE TABLE campus (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES tenant(id), name VARCHAR(100) NOT NULL, address VARCHAR(200) NOT NULL);
CREATE TABLE department (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES tenant(id), name VARCHAR(80) NOT NULL);
CREATE TABLE doctor (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES tenant(id), department_id BIGINT NOT NULL REFERENCES department(id), name VARCHAR(80) NOT NULL, title VARCHAR(60) NOT NULL, specialty VARCHAR(200) NOT NULL);
CREATE TABLE clinic_schedule (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES tenant(id), campus_id BIGINT NOT NULL REFERENCES campus(id), doctor_id BIGINT NOT NULL REFERENCES doctor(id), start_at TIMESTAMP NOT NULL, end_at TIMESTAMP NOT NULL);
CREATE INDEX idx_schedule_doctor_time ON clinic_schedule(tenant_id,doctor_id,start_at,end_at);
CREATE TABLE appointment_slot (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES tenant(id), schedule_id BIGINT NOT NULL REFERENCES clinic_schedule(id), start_at TIMESTAMP NOT NULL, end_at TIMESTAMP NOT NULL, capacity INTEGER NOT NULL, reserved INTEGER NOT NULL DEFAULT 0, UNIQUE(schedule_id,start_at));
CREATE TABLE appointment (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES tenant(id), user_id BIGINT NOT NULL REFERENCES app_user(id), slot_id BIGINT NOT NULL REFERENCES appointment_slot(id), request_key VARCHAR(64) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL, UNIQUE(tenant_id,user_id,request_key));
-- 部分唯一索引允许取消后再次预约，同时阻止同一就诊人重复占用同一时段。
CREATE UNIQUE INDEX uk_active_appointment ON appointment(tenant_id,user_id,slot_id) WHERE status <> 'CANCELLED';
CREATE INDEX idx_appointment_user ON appointment(tenant_id,user_id,id);
CREATE TABLE audit_event (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, tenant_id BIGINT NOT NULL REFERENCES tenant(id), actor_id BIGINT NOT NULL REFERENCES app_user(id), action VARCHAR(40) NOT NULL, target_id BIGINT NOT NULL, created_at TIMESTAMP NOT NULL);
